"""Direct tests for ``helpdesk/query.py``.

Added by Unit 6 of the Django 4.2 -> 5.2 migration. ``test_query.py`` had three tests
for a 258-line query builder, and all three went through the datatables view, so the
builder's own contracts (which filter keys it accepts, how value filters and ISNULL
filters combine, what sorting and pagination do) were never asserted directly.

Every assertion here is on queryset contents or on the serialized payload, never on
generated SQL, so the tests say nothing about which Django version produced them. They
pass unchanged on Django 4.2.30 and 5.2.17.
"""

from datetime import timedelta

from django.contrib.auth import get_user_model
from django.core.exceptions import FieldError
from django.test import TestCase
from django.utils import timezone

from helpdesk.models import FollowUp, KBCategory, KBItem, Queue, Ticket
from helpdesk.query import (
    DATATABLES_COLUMN_NUM_LOOKUP,
    DATATABLES_ORDER_COLUMN_CHOICES,
    __Query__,
    get_search_filter_args,
    query_from_base64,
    query_to_base64,
)
from helpdesk.user import HelpdeskUser


class Base64QueryTests(TestCase):
    """``query_to_base64`` / ``query_from_base64`` are the only way a saved search or a
    datatables URL carries a query, so the round trip is a wire contract."""

    def test_round_trip_preserves_the_query_dict(self):
        query = {
            "filtering": {"status__in": [1, 2]},
            "filtering_null": {"kbitem__isnull": True},
            "sorting": "created",
            "sortreverse": True,
            "search_string": "hello",
        }
        self.assertEqual(query_from_base64(query_to_base64(query)), query)

    def test_a_decoded_query_always_has_a_search_string(self):
        self.assertEqual(query_from_base64(query_to_base64({}))["search_string"], "")

    def test_a_null_search_string_decodes_to_the_empty_string(self):
        # staff.ticket_list seeds search_string with "", but a saved search written by
        # an older release can hold null; query_from_base64 normalises it so that
        # get_search_filter_args' "if not search" guard is reached with a str.
        encoded = query_to_base64({"search_string": None})
        self.assertEqual(query_from_base64(encoded)["search_string"], "")

    def test_the_base64_payload_is_ascii_and_url_safe_enough_for_a_path_segment(self):
        encoded = query_to_base64({"search_string": "café — naïve"})
        self.assertIsInstance(encoded, str)
        encoded.encode("ascii")
        self.assertNotIn("/", encoded.rstrip("="))


class SearchFilterArgTests(TestCase):
    """``get_search_filter_args`` turns the free-text box into a Q object."""

    def test_an_empty_search_produces_an_empty_q(self):
        self.assertEqual(len(get_search_filter_args("").children), 0)
        self.assertEqual(len(get_search_filter_args(None).children), 0)

    def test_a_queue_prefix_searches_only_the_queue_title(self):
        q = get_search_filter_args("queue:Support")
        self.assertEqual(q.children, [("queue__title__icontains", "Support")])

    def test_a_priority_prefix_searches_only_the_priority(self):
        q = get_search_filter_args("priority:1")
        self.assertEqual(q.children, [("priority__icontains", "1")])

    def test_a_plain_search_ors_across_all_ten_searchable_fields(self):
        q = get_search_filter_args("boom")
        self.assertEqual(q.connector, "OR")
        self.assertEqual(len(q.children), 10)
        self.assertEqual({value for _, value in q.children}, {"boom"})

    def test_or_joins_two_terms_into_one_flat_or(self):
        q = get_search_filter_args("alpha OR beta")
        self.assertEqual(q.connector, "OR")
        self.assertEqual(len(q.children), 20)
        self.assertEqual({value for _, value in q.children}, {"alpha", "beta"})

    def test_a_trailing_or_contributes_no_empty_term(self):
        # The "if not subsearch: continue" guard exists for this.
        self.assertEqual(len(get_search_filter_args("alpha OR ").children), 10)


class QueryBuilderFixture(TestCase):
    """Four tickets across two queues, with followups on two of them."""

    @classmethod
    def setUpTestData(cls):
        cls.staff = get_user_model().objects.create_user(
            username="query-staff", is_staff=True, is_superuser=True
        )
        cls.other_staff = get_user_model().objects.create_user(
            username="query-other", is_staff=True
        )
        cls.alpha = Queue.objects.create(title="Alpha", slug="alpha")
        cls.beta = Queue.objects.create(title="Beta", slug="beta")
        category = KBCategory.objects.create(
            title="Cat", slug="cat", description="d", queue=cls.alpha
        )
        cls.kbitem = KBItem.objects.create(
            category=category, title="KB", question="q", answer="a"
        )

        cls.moment = timezone.now() - timedelta(days=7)
        cls.open_ticket = Ticket.objects.create(
            title="alpha open",
            queue=cls.alpha,
            description="needle in the description",
            priority=1,
            status=Ticket.OPEN_STATUS,
            submitter_email="opener@example.com",
        )
        cls.closed_ticket = Ticket.objects.create(
            title="beta closed",
            queue=cls.beta,
            description="unrelated",
            priority=3,
            status=Ticket.CLOSED_STATUS,
            submitter_email="closer@example.com",
            assigned_to=cls.other_staff,
            kbitem=cls.kbitem,
        )
        cls.resolved_ticket = Ticket.objects.create(
            title="alpha resolved",
            queue=cls.alpha,
            description="unrelated",
            priority=5,
            status=Ticket.RESOLVED_STATUS,
            submitter_email="resolver@example.com",
        )
        cls.reopened_ticket = Ticket.objects.create(
            title="beta reopened",
            queue=cls.beta,
            description="unrelated",
            priority=2,
            status=Ticket.REOPENED_STATUS,
            submitter_email="reopener@example.com",
        )

        FollowUp.objects.create(
            ticket=cls.open_ticket, title="first", date=cls.moment
        )
        cls.newest_followup_date = cls.moment + timedelta(hours=5)
        FollowUp.objects.create(
            ticket=cls.open_ticket, title="second", date=cls.newest_followup_date
        )
        FollowUp.objects.create(
            ticket=cls.closed_ticket, title="only", date=cls.moment + timedelta(days=1)
        )

    def build(self, **params):
        """Build a query the way the views do, through the base64 payload."""
        return __Query__(
            HelpdeskUser(self.staff), base64query=query_to_base64(params)
        )

    def ids(self, **params):
        return sorted(ticket.id for ticket in self.build(**params).get())


class ValueFilterTests(QueryBuilderFixture):
    """Each filter key ``helpdesk/views/staff.py`` puts into ``filtering``."""

    def test_no_filters_returns_every_ticket_the_user_may_see(self):
        self.assertEqual(
            self.ids(),
            sorted(
                [
                    self.open_ticket.id,
                    self.closed_ticket.id,
                    self.resolved_ticket.id,
                    self.reopened_ticket.id,
                ]
            ),
        )

    def test_an_empty_filtering_dict_is_the_same_as_no_filters(self):
        self.assertEqual(
            self.ids(filtering={}, filtering_null={}, search_string=""), self.ids()
        )

    def test_status_in_selects_only_the_listed_statuses(self):
        self.assertEqual(
            self.ids(
                filtering={
                    "status__in": [Ticket.OPEN_STATUS, Ticket.REOPENED_STATUS]
                }
            ),
            sorted([self.open_ticket.id, self.reopened_ticket.id]),
        )

    def test_queue_id_in_selects_only_that_queue(self):
        self.assertEqual(
            self.ids(filtering={"queue__id__in": [self.alpha.id]}),
            sorted([self.open_ticket.id, self.resolved_ticket.id]),
        )

    def test_priority_in_selects_only_the_listed_priorities(self):
        self.assertEqual(
            self.ids(filtering={"priority__in": [1, 5]}),
            sorted([self.open_ticket.id, self.resolved_ticket.id]),
        )

    def test_assigned_to_id_in_selects_only_that_owner(self):
        self.assertEqual(
            self.ids(filtering={"assigned_to__id__in": [self.other_staff.id]}),
            [self.closed_ticket.id],
        )

    def test_kbitem_in_selects_only_tickets_on_that_kb_item(self):
        self.assertEqual(
            self.ids(filtering={"kbitem__in": [self.kbitem.pk]}),
            [self.closed_ticket.id],
        )

    def test_created_gte_and_lte_bracket_the_creation_date(self):
        # staff.ticket_list writes these two as a pair for the date range picker.
        created = Ticket.objects.get(pk=self.open_ticket.pk).created
        self.assertEqual(
            self.ids(
                filtering={
                    "created__gte": (created - timedelta(minutes=1)).isoformat(),
                    "created__lte": (created + timedelta(minutes=1)).isoformat(),
                }
            ),
            sorted(
                [
                    self.open_ticket.id,
                    self.closed_ticket.id,
                    self.resolved_ticket.id,
                    self.reopened_ticket.id,
                ]
            ),
        )

    def test_two_value_filters_are_anded_not_ored(self):
        self.assertEqual(
            self.ids(
                filtering={
                    "queue__id__in": [self.alpha.id],
                    "status__in": [Ticket.OPEN_STATUS],
                }
            ),
            [self.open_ticket.id],
        )

    def test_a_value_filter_and_a_search_string_are_anded(self):
        self.assertEqual(
            self.ids(
                filtering={"queue__id__in": [self.alpha.id]}, search_string="needle"
            ),
            [self.open_ticket.id],
        )

    def test_an_unknown_filter_key_raises_field_error_rather_than_being_ignored(self):
        with self.assertRaises(FieldError):
            self.ids(filtering={"no_such_field__in": [1]})

    def test_the_queue_prefilter_hides_tickets_the_user_cannot_reach(self):
        with self.settings(HELPDESK_ENABLE_PER_QUEUE_STAFF_PERMISSION=True):
            visible = __Query__(
                HelpdeskUser(self.other_staff), base64query=query_to_base64({})
            ).get()
        # other_staff is not a superuser and holds no per-queue permission, and
        # neither queue allows public submission, so nothing is reachable.
        self.assertEqual(list(visible), [])


class NullFilterTests(QueryBuilderFixture):
    """``filtering_null`` on its own, and merged with a value filter on the same field."""

    def test_isnull_true_on_its_own_selects_the_unset_rows(self):
        self.assertEqual(
            self.ids(filtering_null={"kbitem__isnull": True}),
            sorted(
                [
                    self.open_ticket.id,
                    self.resolved_ticket.id,
                    self.reopened_ticket.id,
                ]
            ),
        )

    def test_isnull_false_on_its_own_selects_the_set_rows(self):
        self.assertEqual(
            self.ids(filtering_null={"kbitem__isnull": False}),
