                [
                    self.open_ticket.id,
                    self.closed_ticket.id,
                    self.resolved_ticket.id,
                    self.reopened_ticket.id,
                ]
            ),
        )


class SortingTests(QueryBuilderFixture):
    def order(self, **params):
        return [ticket.id for ticket in self.build(**params).get()]

    def test_sorting_orders_ascending_by_default(self):
        self.assertEqual(
            self.order(sorting="priority"),
