    """``get_datatables_context`` is the datatables wire format: the ``draw`` echo, the
    two counts, and a page of serialized rows.

    Its kwargs arrive as ``**request.query_params``, and unpacking a ``QueryDict``
    yields the internal list per key, which is why every read is ``[0]``-indexed.
    """

    def context(self, params=None, **kwargs):
        query = self.build(**(params or {}))
        return query.get_datatables_context(
            **{key: [value] for key, value in kwargs.items()}
        )

