        first = self.context(length="2", start="0", **{"order[0][column]": "0"})
        second = self.context(length="2", start="2", **{"order[0][column]": "0"})
        self.assertEqual([row["id"] for row in first["data"]], [1, 2])
        self.assertEqual([row["id"] for row in second["data"]], [3, 4])
        self.assertEqual(first["recordsTotal"], 4)
        self.assertEqual(second["recordsTotal"], 4)

    def test_a_page_past_the_last_row_is_empty_but_still_reports_the_counts(self):
        context = self.context(length="25", start="100")
        self.assertEqual(context["data"], [])
        self.assertEqual(context["recordsTotal"], 4)
        self.assertEqual(context["recordsFiltered"], 4)

