import re

def fixed(text, ids, pattern):
    if text == "":
        return text
    for match in reversed(list(re.finditer(pattern, text))):
        number = match.groups()[0]
        if int(number) not in ids:
            continue
        text = "%s<a href='/tickets/%s/' class='c'>#%s</a>%s" % (
            text[: match.start()], number, number, text[match.end():],
        )
